create table if not exists public.resident_properties (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, label text not null check (char_length(btrim(label)) between 1 and 120), address text, city text, state text, zip text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.provider_services (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, contractor_id bigint not null references public.contractors(id) on delete cascade, service_name text not null check (char_length(btrim(service_name)) between 1 and 120), active boolean not null default true, created_at timestamptz not null default now(), unique(contractor_id,service_name));
create table if not exists public.community_groups (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, created_by uuid not null references auth.users(id) on delete cascade, name text not null check (char_length(btrim(name)) between 1 and 120), description text, created_at timestamptz not null default now(), unique(workspace_id,name));
alter table public.resident_properties enable row level security; alter table public.provider_services enable row level security; alter table public.community_groups enable row level security;
create policy resident_properties_all on public.resident_properties for all to authenticated using (user_id=auth.uid() and public.hlc_is_workspace_member(workspace_id)) with check (user_id=auth.uid() and public.hlc_is_workspace_member(workspace_id));
create policy provider_services_all on public.provider_services for all to authenticated using (public.hlc_is_workspace_member(workspace_id)) with check (public.hlc_is_workspace_member(workspace_id));
create policy community_groups_select on public.community_groups for select to authenticated using (public.hlc_is_workspace_member(workspace_id));
create policy community_groups_insert on public.community_groups for insert to authenticated with check (created_by=auth.uid() and public.hlc_is_workspace_member(workspace_id));
create policy community_groups_update on public.community_groups for update to authenticated using (created_by=auth.uid() or public.hlc_is_workspace_owner(workspace_id)) with check (public.hlc_is_workspace_member(workspace_id));
create index if not exists resident_properties_user_idx on public.resident_properties(workspace_id,user_id); create index if not exists provider_services_workspace_idx on public.provider_services(workspace_id,contractor_id);
